const int8_t acc_anchor_sleep[][2] = {{17,24},{17,24},{16,23},{16,23},{16,23},{17,24},{17,24},{17,24}};
const uint8_t acc_anchor_sleep_n = 8;

// Head-top anchor (1x sprite coords, scale by 2.5 at draw time).
static inline bool accessoryAnchor(const char* anim, bool faceLeft,
                                   uint8_t frame, int* ax, int* ay) {
  if (!strcmp(anim, "idle") && !faceLeft) {
    const uint8_t i = frame < acc_anchor_idle_n ? frame : 0;
    *ax = acc_anchor_idle[i][0]; *ay = acc_anchor_idle[i][1];
    return true;
  }
  if (!strcmp(anim, "idle") && faceLeft) {
    const uint8_t i = frame < acc_anchor_idle_l_n ? frame : 0;
    *ax = acc_anchor_idle_l[i][0]; *ay = acc_anchor_idle_l[i][1];
    return true;
  }
  if (!strcmp(anim, "idle2") && !faceLeft) {
    const uint8_t i = frame < acc_anchor_idle2_n ? frame : 0;
    *ax = acc_anchor_idle2[i][0]; *ay = acc_anchor_idle2[i][1];
    return true;
  }
  if (!strcmp(anim, "idle2") && faceLeft) {
    const uint8_t i = frame < acc_anchor_idle2_l_n ? frame : 0;
    *ax = acc_anchor_idle2_l[i][0]; *ay = acc_anchor_idle2_l[i][1];
    return true;
  }
  if (!strcmp(anim, "walk") && !faceLeft) {
    const uint8_t i = frame < acc_anchor_walk_n ? frame : 0;
    *ax = acc_anchor_walk[i][0]; *ay = acc_anchor_walk[i][1];
    return true;
  }
  if (!strcmp(anim, "walk") && faceLeft) {
    const uint8_t i = frame < acc_anchor_walk_l_n ? frame : 0;
    *ax = acc_anchor_walk_l[i][0]; *ay = acc_anchor_walk_l[i][1];
    return true;
  }
  if (!strcmp(anim, "jump") && !faceLeft) {
    const uint8_t i = frame < acc_anchor_jump_n ? frame : 0;
    *ax = acc_anchor_jump[i][0]; *ay = acc_anchor_jump[i][1];
    return true;
  }
  if (!strcmp(anim, "jump") && faceLeft) {
    const uint8_t i = frame < acc_anchor_jump_l_n ? frame : 0;
    *ax = acc_anchor_jump_l[i][0]; *ay = acc_anchor_jump_l[i][1];
    return true;
  }
  if (!strcmp(anim, "dig")) {
    const uint8_t i = frame < acc_anchor_dig_n ? frame : 0;
    *ax = acc_anchor_dig[i][0]; *ay = acc_anchor_dig[i][1];
    return true;
  }
  if (!strcmp(anim, "sleep")) {
    const uint8_t i = frame < acc_anchor_sleep_n ? frame : 0;
    *ax = acc_anchor_sleep[i][0]; *ay = acc_anchor_sleep[i][1];
    return true;
  }
  return false;
}
